export const EDITOR_ACCESS_TOKEN_HEADER = 'x-rivet-editor-token';
export const EDITOR_ACCESS_TOKEN_FRAGMENT = 'editorToken';
export const EDITOR_ACCOUNT_PATHS = [
  '/api/account',
  '/api/config',
  '/api/auth/store',
  '/api/auth/logout',
  '/api/auth/browser-launches',
  '/api/preferences',
  '/api/library/browser-launches',
  '/api/integrations',
  '/api/reference-profiles',
];

const VARIANT_MEDIA_PATH =
  /^\/api\/variants\/(?:[^/]+\/static\/|history\/[^/]+\/[^/]+\/(?:preview(?:\/|$)|site\/)|[^/]+\/[^/]+\/references\/[^/]+\/image\/?$)/;

export const isEditorApiPath = (path: string, method = 'GET'): boolean => {
  const pathname = path.split(/[?#]/)[0].toLowerCase();
  if (/^\/api\/variants(?:\/|$)/.test(pathname)) {
    return (
      !['GET', 'HEAD'].includes(method.toUpperCase()) ||
      !VARIANT_MEDIA_PATH.test(pathname)
    );
  }
  return EDITOR_ACCOUNT_PATHS.some(
    (prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`),
  );
};

export const createEditorUrl = ({
  port,
  token,
}: {
  port: number;
  token: string;
}): string => {
  const url = new URL(`http://127.0.0.1:${port}/rivet`);
  url.hash = new URLSearchParams({
    [EDITOR_ACCESS_TOKEN_FRAGMENT]: token,
  }).toString();
  return url.toString();
};
